def late_fee(days_late, amount):
    """Charge one percent per late day, currently capped at ten days."""
    billable_days = min(max(days_late, 0), 10)
    return round(amount * billable_days * 0.01, 2)


def normalize_reference(reference):
    return reference.strip().lower()

from .config import DEFAULT_CURRENCY
from .pricing import late_fee, normalize_reference
from .storage import append_refund


def quote_invoice(reference, amount, days_late, currency=None):
    normalized = normalize_reference(reference)
    return {
        "reference": normalized,
        "currency": currency or DEFAULT_CURRENCY,
        "late_fee": late_fee(days_late, amount),
    }


def record_refund(reference, amount):
    normalized = normalize_reference(reference)
    return append_refund(normalized, amount)

REFUNDS = []


def append_refund(reference, amount):
    record = {"reference": reference, "amount": amount}
    REFUNDS.append(record)
    return record

